CREATE TABLE IF NOT EXISTS ecs_exchange_goods (goods_id BIGINT PRIMARY KEY AUTO_INCREMENT,exchange_integral BIGINT NOT NULL DEFAULT 0,is_exchange BIGINT NOT NULL DEFAULT 0,is_hot BIGINT NOT NULL DEFAULT 0,FOREIGN KEY(goods_id) REFERENCES ecs_goods(goods_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ecs_collect_goods (rec_id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,goods_id BIGINT NOT NULL,add_time BIGINT NOT NULL DEFAULT (UNIX_TIMESTAMP()),is_attention BIGINT NOT NULL DEFAULT 0,UNIQUE(user_id,goods_id),FOREIGN KEY(user_id) REFERENCES ecs_users(user_id),FOREIGN KEY(goods_id) REFERENCES ecs_goods(goods_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ecs_feedback (msg_id BIGINT PRIMARY KEY AUTO_INCREMENT,parent_id BIGINT NOT NULL DEFAULT 0,user_id BIGINT NOT NULL DEFAULT 0,user_name LONGTEXT NOT NULL DEFAULT (''),user_email LONGTEXT NOT NULL DEFAULT (''),msg_title LONGTEXT NOT NULL DEFAULT (''),msg_type BIGINT NOT NULL DEFAULT 0,msg_status BIGINT NOT NULL DEFAULT 1,msg_content LONGTEXT NOT NULL,msg_time BIGINT NOT NULL DEFAULT (UNIX_TIMESTAMP()),message_img LONGTEXT NOT NULL DEFAULT ('0'),order_id BIGINT NOT NULL DEFAULT 0,msg_area BIGINT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ecs_ad (ad_id BIGINT PRIMARY KEY AUTO_INCREMENT,position_id BIGINT NOT NULL DEFAULT 0,media_type BIGINT NOT NULL DEFAULT 0,ad_name LONGTEXT NOT NULL DEFAULT (''),ad_link LONGTEXT NOT NULL DEFAULT (''),ad_code LONGTEXT NOT NULL,start_time BIGINT NOT NULL DEFAULT 0,end_time BIGINT NOT NULL DEFAULT 0,click_count BIGINT NOT NULL DEFAULT 0,enabled BIGINT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ecs_adsense (from_ad BIGINT NOT NULL,referer VARCHAR(190) NOT NULL DEFAULT '',clicks BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(from_ad,referer)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_ecs_activity_active ON ecs_goods_activity(act_type,start_time,end_time,is_finished);
CREATE TABLE IF NOT EXISTS ecs_browsing_history (
  user_id BIGINT NOT NULL,
  goods_id BIGINT NOT NULL,
  viewed_at BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY (user_id, goods_id),
  FOREIGN KEY(user_id) REFERENCES ecs_users(user_id) ON DELETE CASCADE,
  FOREIGN KEY(goods_id) REFERENCES ecs_goods(goods_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ecs_pm (
  pm_id BIGINT PRIMARY KEY AUTO_INCREMENT,
  user_id BIGINT NOT NULL,
  from_user_id BIGINT NOT NULL,
  title LONGTEXT NOT NULL DEFAULT (''),
  content LONGTEXT NOT NULL DEFAULT (''),
  is_read BIGINT NOT NULL DEFAULT 0,
  created_at BIGINT NOT NULL DEFAULT (UNIX_TIMESTAMP()),
  FOREIGN KEY(user_id) REFERENCES ecs_users(user_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ecs_wholesale (
  goods_id BIGINT NOT NULL,
  min_quantity BIGINT NOT NULL,
  price_cents BIGINT NOT NULL,
  PRIMARY KEY (goods_id, min_quantity),
  FOREIGN KEY(goods_id) REFERENCES ecs_goods(goods_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ecs_checkout_selection (
 user_id BIGINT PRIMARY KEY AUTO_INCREMENT, shipping_id BIGINT NOT NULL DEFAULT 0, payment_id BIGINT NOT NULL DEFAULT 0,
 surplus_cents BIGINT NOT NULL DEFAULT 0, integral BIGINT NOT NULL DEFAULT 0, bonus_id BIGINT NOT NULL DEFAULT 0,
 pack_id BIGINT NOT NULL DEFAULT 0, card_id BIGINT NOT NULL DEFAULT 0, insure BIGINT NOT NULL DEFAULT 0,
 need_invoice BIGINT NOT NULL DEFAULT 0, invoice_title LONGTEXT NOT NULL DEFAULT (''), invoice_content LONGTEXT NOT NULL DEFAULT (''),
 oos_policy LONGTEXT NOT NULL DEFAULT ('cancel'), FOREIGN KEY(user_id) REFERENCES ecs_users(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ecs_pack (pack_id BIGINT PRIMARY KEY AUTO_INCREMENT, pack_name LONGTEXT NOT NULL, pack_fee DECIMAL(12,2) NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ecs_card (card_id BIGINT PRIMARY KEY AUTO_INCREMENT, card_name LONGTEXT NOT NULL, card_fee DECIMAL(12,2) NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ecs_redemption (
 redemption_id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,goods_id BIGINT NOT NULL,quantity BIGINT NOT NULL,points BIGINT NOT NULL,
 idempotency_key VARCHAR(100) NOT NULL,created_at BIGINT NOT NULL,UNIQUE(user_id,idempotency_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ecs_promotion_bid (
 bid_id BIGINT PRIMARY KEY AUTO_INCREMENT,promotion_id BIGINT NOT NULL,user_id BIGINT NOT NULL,price_cents BIGINT NOT NULL,
 deposit_cents BIGINT NOT NULL DEFAULT 0,created_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ecs_promotion_version (promotion_id BIGINT PRIMARY KEY AUTO_INCREMENT,version BIGINT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ecs_checkout_audit (order_id BIGINT PRIMARY KEY AUTO_INCREMENT,selection LONGTEXT NOT NULL,discount_cents BIGINT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ecs_cart_offer (user_id BIGINT PRIMARY KEY AUTO_INCREMENT,package_id BIGINT NOT NULL DEFAULT 0,favourable_id BIGINT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ecs_cart_spec(user_id BIGINT NOT NULL,goods_id BIGINT NOT NULL,product_id BIGINT NOT NULL DEFAULT 0,attributes LONGTEXT NOT NULL DEFAULT ('[]'),PRIMARY KEY(user_id,goods_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ecs_order_spec(order_id BIGINT NOT NULL,goods_id BIGINT NOT NULL,product_id BIGINT NOT NULL DEFAULT 0,attributes LONGTEXT NOT NULL DEFAULT ('[]'),PRIMARY KEY(order_id,goods_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ecs_promotion_claim(promotion_id BIGINT PRIMARY KEY AUTO_INCREMENT,order_id BIGINT NOT NULL,user_id BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ecs_user_rank(rank_id BIGINT NOT NULL,rank_name VARCHAR(60) NOT NULL,discount_percent BIGINT NOT NULL DEFAULT 100 CHECK(discount_percent BETWEEN 0 AND 100)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ecs_member_price(goods_id BIGINT NOT NULL,rank_id BIGINT NOT NULL,user_price DECIMAL(12,2) NOT NULL,PRIMARY KEY(goods_id,rank_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ecs_volume_price(goods_id BIGINT NOT NULL,volume_number BIGINT NOT NULL,volume_price DECIMAL(12,2) NOT NULL,PRIMARY KEY(goods_id,volume_number)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ecs_user_membership(user_id BIGINT PRIMARY KEY AUTO_INCREMENT,rank_id BIGINT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ecs_cart_gift(user_id BIGINT NOT NULL,goods_id BIGINT NOT NULL,quantity BIGINT NOT NULL CHECK(quantity>0),PRIMARY KEY(user_id,goods_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ecs_user_write_lock(user_id BIGINT PRIMARY KEY AUTO_INCREMENT,version BIGINT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ecs_payment_intent(intent_sn VARCHAR(64) PRIMARY KEY,order_id BIGINT NOT NULL,user_id BIGINT NOT NULL,pay_id BIGINT NOT NULL,provider VARCHAR(30) NOT NULL,amount_cents BIGINT NOT NULL CHECK(amount_cents>0),status VARCHAR(20) NOT NULL DEFAULT 'pending',created_at BIGINT NOT NULL,expires_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_payment_intent_order ON ecs_payment_intent(order_id,status);
ALTER TABLE ecs_users ADD COLUMN mobile_phone VARCHAR(32) NOT NULL DEFAULT '', ADD COLUMN is_validated BIGINT NOT NULL DEFAULT 0, ADD COLUMN pay_points BIGINT NOT NULL DEFAULT 0;
ALTER TABLE ecs_tag ADD COLUMN authenticated_user_id BIGINT GENERATED ALWAYS AS (NULLIF(user_id,0)) STORED;
CREATE UNIQUE INDEX uk_tag_member ON ecs_tag(authenticated_user_id,goods_id,tag_words);
SET FOREIGN_KEY_CHECKS=1;
